/* Data adapter: replace the sample dataset with validated GeoGuessr match data when an authorized source is available. */
const images=[
 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1800&q=85',
 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1800&q=85',
 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1800&q=85',
 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1800&q=85',
 'https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?auto=format&fit=crop&w=1800&q=85'
];
const profiles=[{id:'nina',name:'Nina',url:''},{id:'caio',name:'Caio',url:''},{id:'leo',name:'Léo',url:''}];
function demoRound(i, seed){const locations=[[-13.1,-58.2],[46.8,8.2],[35.4,137.1],[-25.2,133.7],[48.6,-113.8]]; const c=locations[(i+seed)%locations.length];return {image:images[(i+seed)%images.length],caption:'Paisagem de demonstração',location:{lat:c[0],lng:c[1]},guesses:{A:{lat:c[0]+(seed+1)*2.6,lng:c[1]-4.3},B:{lat:c[0]-3.3,lng:c[1]+(i+1)*2.2}}}}
const demo={profiles,games:['caio','leo','nina'].map((playerId,seed)=>({playerId,target:'A',rounds:Array.from({length:5},(_,i)=>demoRound(i,seed))}))};
let data=structuredClone(demo), gameIndex=0, roundIndex=0, answers={}, map, mapLayer, imported=false;
const $=id=>document.getElementById(id);
function make(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
function render(){
 const game=data.games[gameIndex],round=game.rounds[roundIndex],target=game.target||'A';
 $('gameTabs').replaceChildren();data.games.forEach((g,i)=>{const b=make('button','game-tab'+(i===gameIndex?' active':'')+(answers[i]?' answered':''));b.setAttribute('role','tab');b.setAttribute('aria-selected',String(i===gameIndex));b.append(document.createTextNode('Jogo '+String(i+1).padStart(2,'0')),make('span','tab-num',answers[i]?'✓':String(i+1).padStart(2,'0')));b.onclick=()=>{gameIndex=i;roundIndex=0;render()};$('gameTabs').append(b)});
 const done=Object.keys(answers).length;$('progressText').innerHTML=done+' <small>/ '+data.games.length+'</small>';$('progressBar').style.width=(done/data.games.length*100)+'%';$('currentGame').textContent='Jogo '+String(gameIndex+1).padStart(2,'0');$('selectedCount').textContent=(answers[gameIndex]?1:0)+' / 1';$('roundBadge').textContent='ROUND '+String(roundIndex+1).padStart(2,'0');$('roundLabel').innerHTML=String(roundIndex+1).padStart(2,'0')+' <i>/</i> '+String(game.rounds.length).padStart(2,'0');$('sceneCaption').textContent=round.caption||'Local da rodada';$('scene').style.backgroundImage=round.image?'url("'+round.image.replace(/["\\]/g,'')+'")':'';
 document.querySelector('.side-description').replaceChildren(document.createTextNode('Observe os palpites de '),make('strong','',`★ Jogador ${target}`),document.createTextNode(' e escolha o perfil que você acha que jogou esta partida.'));document.querySelector('.round-summary strong:last-child').innerHTML='<span class="star">★</span> Jogador '+target;
 $('roundDots').replaceChildren();game.rounds.forEach((_,i)=>{const b=make('button',i===roundIndex?'active':'');b.setAttribute('aria-label','Ir para round '+(i+1));b.onclick=()=>{roundIndex=i;render()};$('roundDots').append(b)});
 $('playerOptions').replaceChildren();data.profiles.forEach((p,i)=>{const b=make('button','player-option'+(answers[gameIndex]===p.id?' selected':''));b.setAttribute('aria-pressed',String(answers[gameIndex]===p.id));const av=make('span','avatar',p.name.trim().slice(0,2).toUpperCase());const info=make('span','option-text');info.append(make('strong','',p.name),make('small','',imported?'Perfil importado':'Jogador de exemplo'));b.append(av,info,make('span','radio'));b.onclick=()=>{answers[gameIndex]=p.id;render()};$('playerOptions').append(b)});
 const complete=done===data.games.length;$('submitButton').disabled=!complete;$('submitStatus').innerHTML=complete?'<span>✓</span> Tudo pronto para revelar':'<span>◌</span> Responda todos os jogos para revelar';
 updateMap(round,target);
}
function updateMap(round,target){if(!window.L)return;if(!map){map=L.map('map',{zoomControl:true,scrollWheelZoom:false,attributionControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);mapLayer=L.layerGroup().addTo(map)}mapLayer.clearLayers();const points=[];['A','B'].forEach(letter=>{const p=round.guesses[letter];points.push([p.lat,p.lng]);const icon=L.divIcon({className:'',html:'<div class="map-pin '+letter.toLowerCase()+'">'+letter+(target===letter?'<span>★</span>':'')+'</div>',iconSize:[27,27],iconAnchor:[13,13]});L.marker([p.lat,p.lng],{icon}).addTo(mapLayer)});if(round.location){const p=round.location;points.push([p.lat,p.lng]);L.marker([p.lat,p.lng],{icon:L.divIcon({className:'map-location',html:'✚',iconSize:[20,20],iconAnchor:[10,10]})}).addTo(mapLayer);['A','B'].forEach(letter=>L.polyline([[p.lat,p.lng],[round.guesses[letter].lat,round.guesses[letter].lng]],{color:letter==='A'?'#6f913e':'#688ba2',weight:2,dashArray:'4 4'}).addTo(mapLayer))}map.fitBounds(points,{padding:[28,28],maxZoom:7});setTimeout(()=>map.invalidateSize(),50)}
$('prevRound').onclick=()=>{roundIndex=(roundIndex-1+data.games[gameIndex].rounds.length)%data.games[gameIndex].rounds.length;render()};$('nextRound').onclick=()=>{roundIndex=(roundIndex+1)%data.games[gameIndex].rounds.length;render()};$('expandMap').onclick=()=>{document.querySelector('.map-shell').classList.toggle('expanded');setTimeout(()=>map&&map.invalidateSize(),220)};
$('profilesButton').onclick=()=>$('profileDialog').showModal();$('closeProfiles').onclick=()=>$('profileDialog').close();$('saveProfiles').onclick=()=>{const value=$('profileLinks').value.trim();if(value){const links=value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(links.some(x=>!/^https?:\/\/(www\.)?geoguessr\.com\/user\/[a-z0-9]+\/?$/i.test(x))){$('profileMessage').textContent='Confira os links: use URLs de perfil do GeoGuessr, um por linha.';return}$('profileMessage').textContent='Links anotados nesta sessão. A busca automática ainda não está disponível.'}else $('profileDialog').close()};
$('restartButton').onclick=()=>{answers={};gameIndex=0;roundIndex=0;render()};$('submitButton').onclick=()=>{if(Object.keys(answers).length!==data.games.length)return;let score=0;$('resultList').replaceChildren();data.games.forEach((g,i)=>{const correct=data.profiles.find(p=>p.id===g.playerId),chosen=data.profiles.find(p=>p.id===answers[i]);const ok=correct.id===chosen.id;if(ok)score++;const row=make('div','result-row');const desc=make('div');desc.append(make('small','',`JOGO ${String(i+1).padStart(2,'0')} · VOCÊ ESCOLHEU ${chosen.name.toUpperCase()}`),make('strong','',`Jogador correto: ${correct.name}`));row.append(desc,make('span','status'+(ok?'':' wrong'),ok?'✓':'×'));$('resultList').append(row)});$('score').innerHTML=score+'<span>/'+data.games.length+'</span>';$('scoreMessage').textContent=score===data.games.length?'Você acertou todos os jogadores!':'Cada palpite conta uma história.';$('resultDialog').showModal()};$('closeResults').onclick=()=>$('resultDialog').close();$('playAgain').onclick=()=>{$('resultDialog').close();answers={};gameIndex=0;roundIndex=0;render()};
function validate(d){if(!d||!Array.isArray(d.profiles)||!Array.isArray(d.games)||d.profiles.length<2||d.profiles.length>20||d.games.length!==d.profiles.length)throw Error('Inclua de 2 a 20 perfis e exatamente um jogo por perfil.');const ids=new Set();for(const p of d.profiles){if(typeof p.id!=='string'||!p.id||typeof p.name!=='string'||!p.name.trim()||ids.has(p.id))throw Error('Cada perfil precisa de id único e nome.');ids.add(p.id)}const owners=new Set();const validPoint=p=>p&&Number.isFinite(p.lat)&&p.lat>=-90&&p.lat<=90&&Number.isFinite(p.lng)&&p.lng>=-180&&p.lng<=180;for(const g of d.games){if(!ids.has(g.playerId)||owners.has(g.playerId)||!['A','B'].includes(g.target)||!Array.isArray(g.rounds)||!g.rounds.length||g.rounds.length>50)throw Error('Cada jogo precisa de um playerId único, target A ou B e rounds.');owners.add(g.playerId);for(const r of g.rounds){if(!r.guesses||!validPoint(r.guesses.A)||!validPoint(r.guesses.B)||(r.location&&!validPoint(r.location)))throw Error('Confira as coordenadas dos palpites e locais.');if(r.image&&(!/^https:\/\//i.test(r.image)||typeof r.image!=='string'))throw Error('As imagens devem usar URLs HTTPS.')}}return d}
$('jsonFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('O arquivo deve ter até 1 MB.');const parsed=validate(JSON.parse(await file.text()));data=parsed;imported=true;answers={};gameIndex=roundIndex=0;document.querySelector('.demo-badge').innerHTML='<i></i> PARTIDAS IMPORTADAS';document.querySelector('footer span:last-child').textContent='Dados de partidas importadas';$('profileDialog').close();render()}catch(err){$('profileMessage').textContent='Não foi possível importar: '+err.message}e.target.value=''};
render();
